function copiarLinkLoja(){ var link=getLinkLoja(); if(navigator.clipboard){ navigator.clipboard.writeText(link).then(function(){ alert("✅ Link copiado!\n\n"+link); }); } else { var ta=document.createElement('textarea'); ta.value=link; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); alert("✅ Link copiado! "+link); } }
