function enviarRecuperacao(){ var email=document.getElementById('cliEmailEsqueceu').value.trim(); if(!emailValido(email)) return document.getElementById('msgCliente').innerText="⚠️ Escreve o e-mail completo!"; document.getElementById('msgCliente').innerText="A enviar link..."; auth.sendPasswordResetEmail(email).then(function(){ document.getElementById('msgCliente').innerText="✅ Link enviado para "+email; alert("✅ Link enviado! Vai no teu e-mail "+email); setTimeout(function(){ mostrarTelaLogin(); document.getElementById('cliEmail').value=email; },1500); }).catch(function(e){ document.getElementById('msgCliente').innerText="Erro: Este e-mail não tem conta!"; }); }
