function precisaLogin(){ if(!clienteEmail){ alert("🔒 Para comprar tens de ter conta na EMPIRE!\n\nPodes visitar à vontade, mas para adicionar ao carrinho tens de CRIAR CONTA ou ENTRAR."); abrirLoginCliente(); return true; } return false; }
function entrarCliente(){ var email=document.getElementById('cliEmail').value.trim(); var senha=document.getElementById('cliSenha').value; if(!emailValido(email)) return document.getElementById('msgCliente').innerText="⚠️ Escreve o e-mail completo!"; if(!senha) return document.getElementById('msgCliente').innerText="Escreve a senha!"; document.getElementById('msgCliente').innerText="A entrar..."; auth.signInWithEmailAndPassword(email,senha).then(function(cred){ clienteEmail=cred.user.email; return db.collection("clientes").doc(cred.user.uid).get().then(function(s){ if(s.exists){ clienteNome=s.data().nome||""; } else { clienteNome=""; } document.getElementById('msgCliente').innerText="✅ Entraste! Bem-vindo "+(clienteNome||clienteEmail); setTimeout(function(){ fecharLoginCliente(); atualizarHeaderCliente(); mostrarLoja(); },800); }); }).catch(function(e){ document.getElementById('msgCliente').innerText="❌ E-mail ou senha errada!"; }); }
function criarContaCliente(){ var nome=document.getElementById('cliNomeConta').value.trim(); var email=document.getElementById('cliEmailCriar').value.trim(); var whats=document.getElementById('cliWhatsConta').value.trim(); var senha=document.getElementById('cliSenhaCriar').value; var senha2=document.getElementById('cliSenhaConfirmar').value; if(!nome) return document.getElementById('msgCliente').innerText="⚠️ Escreve o teu nome!"; if(!emailValido(email)) return document.getElementById('msgCliente').innerText="⚠️ Escreve o e-mail completo!"; if(!whats) return document.getElementById('msgCliente').innerText="⚠️ Escreve o teu WhatsApp!"; if(!senha) return document.getElementById('msgCliente').innerText="⚠️ Cria uma senha!"; if(senha.length<6) return document.getElementById('msgCliente').innerText="⚠️ A senha tem de ter no mínimo 6 caracteres!"; if(senha!==senha2) return document.getElementById('msgCliente').innerText="⚠️ As senhas não são iguais!"; document.getElementById('msgCliente').innerText="A criar a tua conta..."; auth.createUserWithEmailAndPassword(email,senha).then(function(cred){ return db.collection("clientes").doc(cred.user.uid).set({nome:nome,email:email,whatsapp:whats,criado:Date.now(),tipo:"cliente"}).then(function(){ document.getElementById('msgCliente').innerText="✅ Conta criada!"; return auth.signOut().then(function(){ alert("✅ Conta criada, "+nome+"!\n\nAgora entra com o e-mail e a senha que acabaste de criar."); fecharLoginCliente(); mostrarLoja(); setTimeout(function(){ abrirLoginCliente(); mostrarTelaLogin(); document.getElementById('cliEmail').value=email; },600); }); }); }).catch(function(e){ document.getElementById('msgCliente').innerText="Erro: "+e.message; }); }
function sairCliente(){ if(confirm("Queres sair da tua conta?")){ auth.signOut().then(function(){ clienteEmail=""; clienteNome=""; isAdmin=false; carrinho=[]; atualizarContadorCarrinho(); atualizarHeaderCliente(); }); } }
function gerarReciboPDF(id){ var found=null; todosPedidos.forEach(function(o){ if(o.id==id) found=o.data; }); if(!found) return alert("Pedido não encontrado!"); var p=found; var data=new Date(p.dataConfirmacao||p.criado||Date.now()); var dataStr=data.toLocaleDateString('pt-PT')+" "+data.toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'}); var numRecibo="EMPIRE-"+String(id).slice(-6).toUpperCase(); var itensHtml=p.itens.map(function(i){ var q=i.qtd||1; return "<tr><td style='padding:10px;border-bottom:1px solid #ddd'>"+i.nome+"</td><td style='padding:10px;border-bottom:1px solid #ddd;text-align:center'>"+q+"x</td><td style='padding:10px;border-bottom:1px solid #ddd;text-align:right'>"+Number(i.preco).toLocaleString()+" Kz</td><td style='padding:10px;border-bottom:1px solid #ddd;text-align:right'><b>"+(Number(i.preco)*q).toLocaleString()+" Kz</b></td></tr>"; }).join(''); var html="<!DOCTYPE html><html><head><meta charset='UTF-8'><title>Recibo "+numRecibo+"</title><style>body{font-family:Arial;padding:30px;color:#000} .top{text-align:center;border-bottom:3px solid #d4af37;padding-bottom:15px} table{width:100%;border-collapse:collapse;margin:20px 0} th{background:#000;color:#fff;padding:12px;text-align:left} .total{text-align:right;font-size:22px;margin-top:10px} .box{background:#f9f9f9;border:1px solid #ddd;padding:15px;border-radius:10px;margin:15px 0} .footer{text-align:center;color:#888;font-size:12px;margin-top:30px;border-top:1px solid #ddd;padding-top:15px} @media print{ .noPrint{display:none} }</style></head><body><div class='top'><h1>EMPIRE 👑</h1><p>LOJA OFICIAL • Luanda, Angola • WhatsApp: +244 972 370 499</p><h2>🧾 RECIBO DE COMPRA</h2></div><div class='box'><b>Nº Recibo:</b> "+numRecibo+"<br><b>Data:</b> "+dataStr+"<br><b>Estado:</b> ✅ PAGAMENTO CONFIRMADO<br><b>Método:</b> "+p.metodo+"</div><div class='box'><b>👤 Cliente:</b> "+p.nome+"<br><b>📱 WhatsApp:</b> "+p.whatsapp+"<br><b>📧 E-mail:</b> "+(p.emailPagamento||p.clienteEmail||"")+"</div><table><tr><th>Produto</th><th style='text-align:center'>Qtd</th><th style='text-align:right'>Preço</th><th style='text-align:right'>Subtotal</th></tr>"+itensHtml+"</table><div class='total'>TOTAL PAGO: <b style='color:#b8860b'>"+Number(p.total).toLocaleString()+" Kz</b></div><div class='footer'>EMPIRE © 2026 • Este recibo confirma que o pagamento foi recebido.</div><div class='noPrint' style='text-align:center;margin-top:20px'><button onclick='window.print()' style='background:#d4af37;border:0;padding:15px 30px;border-radius:30px;font-weight:800;cursor:pointer;font-size:16px'>🖨️ IMPRIMIR / GUARDAR COMO PDF</button></div></body></html>"; var win=window.open('','_blank'); win.document.write(html); win.document.close(); }
function enviarReciboWhatsApp(id){ var found=null; todosPedidos.forEach(function(o){ if(o.id==id) found=o.data; }); if(!found) return; var p=found; var numRecibo="EMPIRE-"+String(id).slice(-6).toUpperCase(); var whatsCliente=String(p.whatsapp||"").replace(/\D/g,''); if(!whatsCliente) return alert("Este cliente não tem WhatsApp!"); if(whatsCliente.length==9) whatsCliente="244"+whatsCliente; var msg="Olá "+p.nome+"! 👑%0A%0AObrigado pela tua compra na EMPIRE!%0A%0A🧾 Recibo Nº: "+numRecibo+"%0AMétodo: "+p.metodo+"%0A"+p.itens.map(function(i){return "- "+(i.qtd||1)+"x "+i.nome+" - "+(Number(i.preco)*(i.qtd||1))+" Kz"}).join("%0A")+"%0A%0ATOTAL PAGO: "+Number(p.total).toLocaleString()+" Kz ✅%0A%0AEMPIRE 👑 • Luanda • "+getLinkLoja(); window.open("https://wa.me/"+whatsCliente+"?text="+msg,"_blank"); alert("✅ WhatsApp aberto para "+p.nome+"!"); }
function enviarReciboEmail(id){ var found=null; todosPedidos.forEach(function(o){ if(o.id==id) found=o.data; }); if(!found) return; var p=found; var emailCliente=p.emailPagamento||p.clienteEmail||""; if(!emailCliente){ emailCliente=prompt("Escreve o e-mail dele:"); if(!emailCliente) return; } var numRecibo="EMPIRE-"+String(id).slice(-6).toUpperCase(); var assunto=encodeURIComponent("🧾 Recibo EMPIRE - "+numRecibo); var corpo=encodeURIComponent("Olá "+p.nome+"! 👑\n\nObrigado pela tua compra na EMPIRE!\n\n🧾 Recibo Nº: "+numRecibo+"\nMétodo: "+p.metodo+"\n"+p.itens.map(function(i){return "- "+(i.qtd||1)+"x "+i.nome+" - "+(Number(i.preco)*(i.qtd||1))+" Kz"}).join("\n")+"\n\nTOTAL PAGO: "+Number(p.total).toLocaleString()+" Kz ✅\n\nEMPIRE 👑 • Luanda"); window.open("mailto:"+emailCliente+"?subject="+assunto+"&body="+corpo,"_blank"); }
function aplicarLoja(){ document.getElementById('logoTexto').innerHTML = LOJA.nomeLoja + '<span>👑</span>'; document.getElementById('logoSlogan').innerText = LOJA.sloganLoja; document.title = LOJA.nomeLoja + ' 👑 - Loja Oficial'; var lb=document.getElementById('logoImgBox'); lb.innerHTML = LOJA.logoImg ? '<img src="'+LOJA.logoImg+'">' : ''; var bi=document.getElementById('bannerImg'); if(LOJA.bannerImg){ bi.src=LOJA.bannerImg; bi.style.display='block'; } else bi.style.display='none'; document.getElementById('bannerTitulo').innerHTML = LOJA.bannerTitulo; document.getElementById('bannerSub').innerText = LOJA.bannerSub; document.getElementById('sobreTitulo').innerText = LOJA.sobreTitulo; document.getElementById('sobreTexto').innerText = LOJA.sobreTexto; document.getElementById('visaoTexto').innerText = LOJA.visao; document.getElementById('missaoTexto').innerText = LOJA.missao; document.getElementById('sobreExtra').innerText = LOJA.sobreExtra; document.getElementById('footerTexto').innerText = LOJA.footer; document.getElementById('cfgNomeLoja').value = LOJA.nomeLoja; document.getElementById('cfgSloganLoja').value = LOJA.sloganLoja; document.getElementById('cfgBannerTitulo').value = LOJA.bannerTitulo; document.getElementById('cfgBannerSub').value = LOJA.bannerSub; document.getElementById('cfgSobreTitulo').value = LOJA.sobreTitulo; document.getElementById('cfgSobreTexto').value = LOJA.sobreTexto; document.getElementById('cfgVisao').value = LOJA.visao; document.getElementById('cfgMissao').value = LOJA.missao; document.getElementById('cfgSobreExtra').value = LOJA.sobreExtra; document.getElementById('cfgFooter').value = LOJA.footer; if(LOJA.logoImg){ var p=document.getElementById('prevLogo'); p.src=LOJA.logoImg; p.style.display='block'; } if(LOJA.bannerImg){ var pb=document.getElementById('prevBanner'); pb.src=LOJA.bannerImg; pb.style.display='block'; } }
function salvarLoja(){ LOJA.nomeLoja = document.getElementById('cfgNomeLoja').value.trim() || "EMPIRE"; LOJA.sloganLoja = document.getElementById('cfgSloganLoja').value.trim() || "LOJA OFICIAL"; LOJA.bannerTitulo = document.getElementById('cfgBannerTitulo').value.trim() || "ESTILO QUE IMPÕE RESPEITO"; LOJA.bannerSub = document.getElementById('cfgBannerSub').value.trim(); LOJA.sobreTitulo = document.getElementById('cfgSobreTitulo').value.trim() || "👑 Sobre a EMPIRE"; LOJA.sobreTexto = document.getElementById('cfgSobreTexto').value.trim(); LOJA.visao = document.getElementById('cfgVisao').value.trim(); LOJA.missao = document.getElementById('cfgMissao').value.trim(); LOJA.sobreExtra = document.getElementById('cfgSobreExtra').value.trim(); LOJA.footer = document.getElementById('cfgFooter').value.trim(); db.collection("config").doc("loja").set(LOJA).then(function(){ aplicarLoja(); alert("Loja personalizada e salva ✅"); }); }
function lerLogo(e){ var f=e.target.files[0]; if(!f) return; if(f.size>600000){alert("Logo muito grande!");return;} var r=new FileReader(); r.onload=function(ev){ LOJA.logoImg=ev.target.result; var p=document.getElementById('prevLogo'); p.src=LOJA.logoImg; p.style.display='block'; }; r.readAsDataURL(f); }
function removerLogo(){ LOJA.logoImg=""; document.getElementById('prevLogo').style.display='none'; document.getElementById('inputLogo').value=""; alert("Logo removido. Clica em SALVAR."); }
function lerBanner(e){ var f=e.target.files[0]; if(!f) return; if(f.size>800000){alert("Banner muito grande!");return;} var r=new FileReader(); r.onload=function(ev){ LOJA.bannerImg=ev.target.result; var p=document.getElementById('prevBanner'); p.src=LOJA.bannerImg; p.style.display='block'; }; r.readAsDataURL(f); }
function removerBanner(){ LOJA.bannerImg=""; document.getElementById('prevBanner').style.display='none'; document.getElementById('inputBanner').value=""; alert("Banner removido. Clica em SALVAR."); }
function toggleDestaque(id,atual){ db.collection("produtos").doc(id).update({destaque:!atual}).then(function(){ alert(!atual ? "⭐ Produto colocado em DESTAQUE!" : "Produto tirado de Destaque"); }); }
function abrirComprovativo(p){ if(!p.comprovativo) return alert("Sem comprovativo"); var tipo=p.comprovativoTipo||""; var nome=(p.comprovativoNome||"").toLowerCase(); var isPdf=tipo.indexOf('pdf')>=0||nome.indexOf('.pdf')>=0; var isImage=tipo.indexOf('image')>=0||nome.match(/\.(jpg|jpeg|png|gif|webp)$/); if(isPdf){ var win=window.open(); win.document.write('<iframe src="'+p.comprovativo+'" style="width:100%;height:100vh;border:0"></iframe>'); } else if(isImage){ abrirImg(p.comprovativo); } else { var a=document.createElement('a'); a.href=p.comprovativo; a.download=p.comprovativoNome||"comprovativo"; a.target="_blank"; a.click(); } }
function htmlComprovativo(p){ if(!p.comprovativo) return "<p class='small'>SEM COMPROVATIVO</p>"; var tipo=p.comprovativoTipo||""; var nome=(p.comprovativoNome||"").toLowerCase(); var isPdf=tipo.indexOf('pdf')>=0||nome.indexOf('.pdf')>=0; var isImage=tipo.indexOf('image')>=0||nome.match(/\.(jpg|jpeg|png|gif|webp)$/)||(!tipo&&p.comprovativo.indexOf('data:image')==0); if(isPdf){ return '<div class="docBox"><div style="font-size:40px">📄</div><b>PDF - '+(p.comprovativoNome||"comprovativo.pdf")+'</b><br><button class="btn" style="background:#ff4444;margin-top:10px" onclick="abrirComprovativoPorId(\''+p._id+'\')">📄 ABRIR PDF</button></div>'; } else if(isImage){ return '<img class="comp" src="'+p.comprovativo+'" onclick="abrirComprovativoPorId(\''+p._id+'\')"><p class="small" style="color:#d4af37;text-align:center">👆 Clica para abrir em grande</p>'; } else { return '<div class="docBox"><div style="font-size:40px">📎</div><b>Documento - '+(p.comprovativoNome||"comprovativo")+'</b><br><button class="btn" style="background:#0072ff;margin-top:10px" onclick="abrirComprovativoPorId(\''+p._id+'\')">📎 ABRIR DOCUMENTO</button></div>'; } }
function abrirComprovativoPorId(id){ var found=null; todosPedidos.forEach(function(o){ if(o.id==id) found=o.data; }); if(found) abrirComprovativo(found); }
function dataDeHoje(){ var d=new Date(); return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); }
function dataDeOntem(){ var d=new Date(); d.setDate(d.getDate()-1); return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); }
function atualizarMarcacaoData(){ var sel=document.getElementById('dataRel').value; var hoje=dataDeHoje(); var ontem=dataDeOntem(); var bH=document.getElementById('btnHoje'); var bO=document.getElementById('btnOntem'); var msg=document.getElementById('dataSelecionadaMsg'); bH.classList.remove('btnDataAtivo'); bO.classList.remove('btnDataAtivo'); bH.innerText='📅 HOJE'; bO.innerText='📅 ONTEM'; if(sel==hoje){ bH.classList.add('btnDataAtivo'); bH.innerText='✅ HOJE - A VER'; msg.innerText='👉 Estás a ver: HOJE ('+sel+')'; } else if(sel==ontem){ bO.classList.add('btnDataAtivo'); bO.innerText='✅ ONTEM - A VER'; msg.innerText='👉 Estás a ver: ONTEM ('+sel+')'; } else { msg.innerText='👉 Estás a ver: '+sel; } }
function verHoje(){ document.getElementById('dataRel').value=dataDeHoje(); renderRelatorio(); }
function verOntem(){ document.getElementById('dataRel').value=dataDeOntem(); renderRelatorio(); }
function diaDe(ts){ var d=new Date(ts); return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); }
function renderRelatorio(){ var dataEscolhida=document.getElementById('dataRel').value||dataDeHoje(); if(!document.getElementById('dataRel').value) document.getElementById('dataRel').value=dataEscolhida; atualizarMarcacaoData(); var doDia=todosPedidos.filter(function(o){ var ts=o.data.dataConfirmacao||o.data.criado; return diaDe(ts)==dataEscolhida; }); var conf=doDia.filter(function(o){ return o.data.estado&&o.data.estado.indexOf('Confirmado')>=0; }); var pend=doDia.filter(function(o){ return !o.data.estado||o.data.estado.indexOf('Pendente')>=0; }); var rec=doDia.filter(function(o){ return o.data.estado&&o.data.estado.indexOf('Recusado')>=0; }); var totalDia=conf.reduce(function(s,o){ return s+Number(o.data.total||0); },0); document.getElementById('relTotal').innerText=totalDia.toLocaleString()+' Kz'; document.getElementById('relQtd').innerText=conf.length; document.getElementById('relPend').innerText=pend.length; document.getElementById('relRec').innerText=rec.length; var confGeral=todosPedidos.filter(function(o){ return o.data.estado&&o.data.estado.indexOf('Confirmado')>=0; }); var totalGeral=confGeral.reduce(function(s,o){ return s+Number(o.data.total||0); },0); document.getElementById('relTotalGeral').innerText=totalGeral.toLocaleString()+' Kz'; document.getElementById('relQtdGeral').innerText=confGeral.length; var div=document.getElementById('listaRel'); if(!conf.length){ div.innerHTML='<p class="small">Nenhuma venda confirmada neste dia.</p>'; } else{ div.innerHTML=conf.map(function(o){ var p=o.data; var itens=p.itens.map(function(i){return (i.qtd||1)+'x '+i.nome}).join(', '); return '<div class="relItem"><img src="'+(p.itens[0]&&p.itens[0].foto?p.itens[0].foto:'')+'" onerror="this.style.display=\'none\'"><div style="flex:1"><b>'+p.nome+' ('+(p.clienteEmail||'sem conta')+')</b><br><span class="small">'+itens+' • '+p.metodo+'</span></div><b style="color:#00ff88">'+Number(p.total).toLocaleString()+' Kz</b></div>'; }).join(''); } var cont={}; conf.forEach(function(o){ o.data.itens.forEach(function(i){ var q=i.qtd||1; if(!cont[i.nome]) cont[i.nome]={qtd:0,total:0,foto:i.foto||''}; cont[i.nome].qtd+=q; cont[i.nome].total+=Number(i.preco)*q; }); }); var top=Object.keys(cont).map(function(k){ return {nome:k,qtd:cont[k].qtd,total:cont[k].total,foto:cont[k].foto}; }).sort(function(a,b){return b.qtd-a.qtd}); var divTop=document.getElementById('listaTop'); if(!top.length) divTop.innerHTML='<p class="small">Ainda sem vendas confirmadas.</p>'; else divTop.innerHTML=top.map(function(t){ return '<div class="relItem"><img src="'+(t.foto||'')+'" onerror="this.style.display=\'none\'"><div style="flex:1"><b>'+t.nome+'</b><br><span class="small">'+t.qtd+'x vendido(s)</span></div><b>'+t.total.toLocaleString()+' Kz</b></div>'; }).join(''); }
function cardHtml(obj,isDestaqueSec){ var p=obj.data; var id=obj.id; var fotos=p.fotos&&p.fotos.length?p.fotos:(p.foto?[p.foto]:['https://via.placeholder.com/300?text=EMPIRE']); var fotoSafe=fotos[0].replace(/'/g,''); var badge=p.destaque?'<span class="badgeDestaque">⭐ DESTAQUE</span>':'<span class="badgeNovo">NOVO</span>'; var badgeFotos=fotos.length>1?'<span class="badgeQtd">📸 '+fotos.length+' fotos</span>':''; var btnComprar = clienteEmail ? '<button onclick="addCarrinho(\''+id+'\',\''+p.nome.replace(/'/g,'')+'\',\''+p.preco+'\',\''+fotoSafe+'\')">🛒 ADICIONAR</button>' : '<button class="btnBloqueado" onclick="precisaLogin()">🔒 ENTRAR PARA COMPRAR</button>'; return '<div class="card '+(p.destaque?'destaqueCard':'')+'"><div style="position:relative"><img class="main" src="'+fotos[0]+'" onclick="trocarFotoPrincipal(this,\''+id+'\')" style="cursor:pointer">'+badgeFotos+badge+'</div><div class="info"><h3>'+p.nome+'</h3><p>'+(p.desc||'Produto original EMPIRE 👑')+'</p><div class="precoRow"><div class="preco">'+Number(p.preco).toLocaleString()+' Kz</div><span style="font-size:11px;color:#00ff88">● Disponível</span></div>'+btnComprar+'</div></div>'; }
function trocarFotoPrincipal(img,id){ var obj=null; todosProdutos.forEach(function(o){ if(o.id==id) obj=o; }); if(!obj) return; var fotos=obj.data.fotos&&obj.data.fotos.length?obj.data.fotos:(obj.data.foto?[obj.data.foto]:[]); if(fotos.length<=1) return; var atual=fotos.indexOf(img.src); var prox=(atual+1)%fotos.length; img.src=fotos[prox]; }
function renderProdutos(){ var div=document.getElementById('produtos'); var lista=todosProdutos.filter(function(p){ var cat=(p.data.categoria||'').toLowerCase(); var okFiltro=filtroAtual=='todos'||cat==filtroAtual||(p.nome||'').toLowerCase().indexOf(filtroAtual)>=0||(p.desc||'').toLowerCase().indexOf(filtroAtual)>=0; var okPesq=!termoPesquisa||(p.nome||'').toLowerCase().indexOf(termoPesquisa)>=0||(p.desc||'').toLowerCase().indexOf(termoPesquisa)>=0; return okFiltro&&okPesq; }); document.getElementById('qtdMostra').innerText=lista.length+" produto(s)"; document.getElementById('statProd').innerText=todosProdutos.length; var destaques=todosProdutos.filter(function(o){ return o.data.destaque; }); var areaD=document.getElementById('areaDestaque'); var divD=document.getElementById('produtosDestaque'); if(destaques.length){ areaD.style.display='block'; divD.innerHTML=destaques.map(function(o){ return cardHtml(o,true); }).join(''); } else areaD.style.display='none'; if(!lista.length){ div.innerHTML='<div style="text-align:center;padding:40px;color:#888">Nenhum produto nesta categoria.</div>'; return; } div.innerHTML=lista.map(function(o){ return cardHtml(o,false); }).join(''); }
function setFiltro(f,btn){ filtroAtual=f; document.querySelectorAll('.filtros button').forEach(function(b){b.classList.remove('ativo')}); btn.classList.add('ativo'); renderProdutos(); }
function filtrar(){ termoPesquisa=document.getElementById('pesquisa').value.toLowerCase(); renderProdutos(); }
