function recuarParaCarrinho(){ document.getElementById('pagModal').style.display='none'; renderCarrinho(); document.getElementById('cartModal').style.display='flex'; }
function recuarParaLoja(){ document.getElementById('cartModal').style.display='none'; document.getElementById('pagModal').style.display='none'; mostrarLoja(); window.scrollTo(0,0); }
function mostrarAba(qual){ document.getElementById('abaProd').style.display = qual=='prod' ? 'block' : 'none'; document.getElementById('abaPed').style.display = qual=='ped' ? 'block' : 'none'; document.getElementById('abaRel').style.display = qual=='rel' ? 'block' : 'none'; document.getElementById('abaLoja').style.display = qual=='loja' ? 'block' : 'none'; document.getElementById('abaPag').style.display = qual=='pag' ? 'block' : 'none'; document.getElementById('abaCli').style.display = qual=='cli' ? 'block' : 'none'; document.getElementById('tabProd').classList.toggle('ativo',qual=='prod'); document.getElementById('tabPed').classList.toggle('ativo',qual=='ped'); document.getElementById('tabRel').classList.toggle('ativo',qual=='rel'); document.getElementById('tabLoja').classList.toggle('ativo',qual=='loja'); document.getElementById('tabPag').classList.toggle('ativo',qual=='pag'); document.getElementById('tabCli').classList.toggle('ativo',qual=='cli'); if(qual=='rel') renderRelatorio(); if(qual=='cli') renderClientes(); }
