if(auth){
  try{ auth.setPersistence(firebase.auth.Auth.Persistence.LOCAL); }catch(e){}
  auth.onAuthStateChanged(function(u){
    if(!u) return;
    db.collection("clientes").doc(u.uid).get().then(function(s){
      if(s.exists){
        clienteEmail=u.email; clienteNome=s.data().nome||""; isAdmin=false; atualizarHeaderCliente();
      } else {
        isAdmin=true; modoAdmin=true; clienteEmail=u.email; clienteNome="Admin";
        var b=document.getElementById('btnAdminEscondido'); if(b) b.style.display='block';
        atualizarHeaderCliente();
      }
    });
  });
}
function editar(id){ db.collection("produtos").doc(id).get().then(function(s){ if(!s.exists) return; var p=s.data(); document.getElementById('nome').value=p.nome||""; document.getElementById('preco').value=p.preco||""; document.getElementById('desc').value=p.desc||""; document.getElementById('chkDestaque').checked=!!p.destaque; document.getElementById('categoria').value=p.categoria||"outro"; fotosArray=p.fotos&&p.fotos.length?p.fotos.slice():(p.foto?[p.foto]:[]); renderPreview(); editandoId=id; document.getElementById('adminTitle').innerText="✏️ A editar: "+p.nome; document.getElementById('btnSalvar').innerText="💾 SALVAR ALTERAÇÃO"; document.getElementById('btnCancelar').style.display="block"; mostrarAba('prod'); mostrarAdmin(); }); }
function cancelarEdicao(){ editandoId=null; fotosArray=[]; renderPreview(); document.getElementById('nome').value=""; document.getElementById('preco').value=""; document.getElementById('desc').value=""; document.getElementById('chkDestaque').checked=false; document.getElementById('categoria').value="perfume"; document.getElementById('adminTitle').innerText="Adicionar Produto"; document.getElementById('btnSalvar').innerText="+ ADICIONAR PRODUTO À LOJA"; document.getElementById('btnCancelar').style.display="none"; }
function salvarProduto(){ var nome=document.getElementById('nome').value, preco=document.getElementById('preco').value, desc=document.getElementById('desc').value, dest=document.getElementById('chkDestaque').checked, cat=document.getElementById('categoria').value||"outro"; if(!nome||!preco) return alert("Preenche nome e preço"); if(!fotosArray.length) return alert("Escolhe pelo menos 1 foto!"); if(editandoId){ db.collection("produtos").doc(editandoId).update({nome:nome,preco:Number(preco),fotos:fotosArray,foto:fotosArray[0],desc:desc,destaque:dest,categoria:cat}).then(function(){alert("Editado ✅"); cancelarEdicao();}); } else { db.collection("produtos").add({nome:nome,preco:Number(preco),fotos:fotosArray,foto:fotosArray[0],desc:desc,destaque:dest,categoria:cat,criado:Date.now()}).then(function(){alert("Adicionado ✅ - Já aparece para os clientes!"); cancelarEdicao();}).catch(function(e){ alert("Erro ao salvar: "+e.message); }); } }
function apagar(id){ if(confirm("Apagar?")) db.collection("produtos").doc(id).delete(); }
function atualizarContadorCarrinho(){ var totalQtd=carrinho.reduce(function(s,i){ return s+(i.qtd||1); },0); document.getElementById('cartCount').innerText=totalQtd; document.getElementById('cartCountTop').innerText=totalQtd; }
function addCarrinho(id,nome,preco,foto){ if(precisaLogin()) return; var achado=null; carrinho.forEach(function(it){ if(it.id==id) achado=it; }); if(achado){ achado.qtd=(achado.qtd||1)+1; } else { carrinho.push({id:id,nome:nome,preco:Number(preco),foto:foto||'',qtd:1}); } atualizarContadorCarrinho(); alert(nome+" adicionado! Qtd: "+(achado?achado.qtd:1)); }
function aumentarQtd(index){ carrinho[index].qtd=(carrinho[index].qtd||1)+1; renderCarrinho(); atualizarContadorCarrinho(); }
function diminuirQtd(index){ var q=(carrinho[index].qtd||1)-1; if(q<=0){ if(confirm("Remover "+carrinho[index].nome+" do carrinho?")) carrinho.splice(index,1); } else carrinho[index].qtd=q; renderCarrinho(); atualizarContadorCarrinho(); }
function removerItemCarrinho(index){ if(confirm("Remover?")){ carrinho.splice(index,1); renderCarrinho(); atualizarContadorCarrinho(); } }
function verCarrinho(){ if(precisaLogin()) return; renderCarrinho(); document.getElementById('cartModal').style.display='flex'; }
document.getElementById('cart').onclick=function(){ if(precisaLogin()) return; renderCarrinho(); document.getElementById('cartModal').style.display='flex'; };
function renderCarrinho(){ var total=0,html=""; carrinho.forEach(function(it,i){ var q=it.qtd||1; var sub=it.preco*q; total+=sub; html+='<div class="item"><img src="'+(it.foto||'')+'" onerror="this.src=\'https://via.placeholder.com/100?text=EMPIRE\'"><div class="itemInfo"><b>'+it.nome+'</b><span>'+it.preco.toLocaleString()+' Kz cada</span><div style="margin-top:8px"><div class="qtdBox"><button class="qtdBtn menos" onclick="diminuirQtd('+i+')">−</button><span class="qtdNum">'+q+'</span><button class="qtdBtn mais" onclick="aumentarQtd('+i+')">+</button></div></div></div><div class="itemTotal"><b>'+sub.toLocaleString()+' Kz</b><br><span style="font-size:11px;color:#ff4444;cursor:pointer" onclick="removerItemCarrinho('+i+')">🗑️ Remover</span></div></div>'; }); document.getElementById('cartItems').innerHTML=html||"Carrinho vazio"; document.getElementById('cartTotal').innerText="Total: "+total.toLocaleString()+" Kz"; }
function fecharCarrinho(){ document.getElementById('cartModal').style.display='none'; }
function abrirPagamento(){ if(precisaLogin()) return; if(!carrinho.length) return alert("Carrinho vazio!"); document.getElementById('cartModal').style.display='none'; var total=carrinho.reduce(function(s,i){return s+i.preco*(i.qtd||1)},0); document.getElementById('pagResumo').innerText=carrinho.map(function(i){return "- "+(i.qtd||1)+"x "+i.nome+" = "+(i.preco*(i.qtd||1)).toLocaleString()+" Kz"}).join("\n")+"\nTotal: "+total.toLocaleString()+" Kz"; document.getElementById('pagCliente').innerText="👤 Comprar como: "+clienteEmail; document.getElementById('cliEmailPag').value=clienteEmail||document.getElementById('cliEmailPag').value||""; document.getElementById('pagModal').style.display='flex'; }
function fecharPagamento(){ document.getElementById('pagModal').style.display='none'; }
function mostrarDadosPag(){ var sel=document.getElementById('metodoPag').value; var box=document.getElementById('infoPag'); var DADOS=getDadosPag(); if(sel&&DADOS[sel]){ box.style.display='block'; box.innerText='💳 Paga para:\n'+DADOS[sel]; } else box.style.display='none'; }
function lerComprovativo(e){ var f=e.target.files[0]; if(!f) return; if(f.size>3000000){ alert("Ficheiro muito grande! Máximo 3MB."); e.target.value=""; return; } comprovativoNome=f.name; comprovativoTipo=f.type||""; var r=new FileReader(); r.onload=function(ev){ comprovativoBase64=ev.target.result; var box=document.getElementById('prevCompBox'); var isImage=f.type.indexOf('image')>=0; var isPdf=f.type.indexOf('pdf')>=0||f.name.toLowerCase().indexOf('.pdf')>=0; if(isImage){ box.innerHTML='<img src="'+comprovativoBase64+'" style="width:100%;border-radius:12px;margin-top:8px;border:1px solid #333">'; } else if(isPdf){ box.innerHTML='<div style="background:#fff;color:#000;padding:16px;border-radius:12px;margin-top:8px"><div style="font-size:36px">📄</div><b>'+f.name+'</b><br><span class="small">PDF carregado</span></div>'; } else { box.innerHTML='<div style="background:#fff;color:#000;padding:16px;border-radius:12px;margin-top:8px"><div style="font-size:36px">📎</div><b>'+f.name+'</b><br><span class="small">Documento carregado</span></div>'; } var m=document.getElementById('compMsg'); m.innerText='✅ Comprovativo carregado: '+f.name; m.style.color='#00ff88'; }; r.readAsDataURL(f); }
function confirmarPedido(){ if(precisaLogin()) return; var nome=document.getElementById('cliNome').value.trim(); var whats=document.getElementById('cliWhats').value.trim(); var emailPag=document.getElementById('cliEmailPag').value.trim(); var metodo=document.getElementById('metodoPag').value; var total=carrinho.reduce(function(s,i){return s+i.preco*(i.qtd||1)},0); if(!nome||!whats) return alert("Preenche nome e WhatsApp"); if(emailPag && !emailValido(emailPag)) return alert("⚠️ O e-mail está mal escrito!"); if(!metodo) return alert("Escolhe o método"); if(!comprovativoBase64) return alert("⚠️ Tens de subir o COMPROVATIVO!"); var numeroLoja=(CFG.whats||"244972370499").replace(/\D/g,''); db.collection("pedidos").add({ nome:nome, whatsapp:whats, emailPagamento:emailPag||"", metodo:metodo, comprovativo:comprovativoBase64||"", comprovativoNome:comprovativoNome||"", comprovativoTipo:comprovativoTipo||"", itens:carrinho, total:total, estado:"Pendente", clienteEmail:clienteEmail, clienteNome:clienteNome, criado:Date.now() }).then(function(){ var msg="Olá EMPIRE 👑 Novo Pedido:%0ACliente: "+nome+"%0AConta: "+clienteEmail+"%0AWhats: "+whats+"%0AMétodo: "+metodo+"%0A"+carrinho.map(function(i){return "- "+(i.qtd||1)+"x "+i.nome+" - "+(i.preco*(i.qtd||1))+" Kz"}).join("%0A")+"%0ATotal: "+total+" Kz"; window.open("https://wa.me/"+numeroLoja+"?text="+msg,"_blank"); alert("Pedido enviado ✅"); carrinho=[]; atualizarContadorCarrinho(); comprovativoBase64=""; comprovativoNome=""; comprovativoTipo=""; document.getElementById('prevCompBox').innerHTML=''; document.getElementById('inputComp').value=''; document.getElementById('compMsg').innerText='⚠️ Ainda não subiste o comprovativo'; document.getElementById('compMsg').style.color='#ff4444'; document.getElementById('pagModal').style.display='none'; }); }
function confirmarEntrega(id){ db.collection("pedidos").doc(id).update({estado:"Confirmado ✅", dataConfirmacao:Date.now()}).then(function(){alert("Pedido confirmado!")}); }
function recusarPedido(id){ if(confirm("Recusar este pedido?")){ db.collection("pedidos").doc(id).update({estado:"Recusado ❌", dataConfirmacao:Date.now()}).then(function(){alert("Pedido recusado ❌");}); } }
function apagarPedido(id){ if(confirm("Apagar pedido?")) db.collection("pedidos").doc(id).delete(); }
